import { createHash } from 'crypto';
import {
  LOCAL_SOURCE_POLL_MS,
  SOURCE_SYNC_JITTER_MS,
  SOURCE_SYNC_STALE_MS,
  type SourceSyncChecks,
} from '../../types/source-sync';
import { createLogger } from '../../utils/logger';

interface SourceSyncScheduleOptions {
  checks: () => Promise<SourceSyncChecks | null>;
  refresh: (input: SourceSyncChecks & { signal: AbortSignal }) => Promise<void>;
}

const MAX_TIMER_MS = 2_147_483_647;
const MIN_WAKE_MS = 1_000;
const log = createLogger('SourceSyncSchedule');

export const remoteSourceInterval = (sourceId: string): number =>
  SOURCE_SYNC_STALE_MS +
  (createHash('sha256').update(sourceId).digest().readUInt32BE(0) %
    SOURCE_SYNC_JITTER_MS);

export class SourceSyncSchedule {
  private timer?: ReturnType<typeof setTimeout>;
  private cycle?: Promise<void>;
  private wake?: Promise<void>;
  private readonly abort = new AbortController();
  private isStarted = false;

  constructor(private readonly options: SourceSyncScheduleOptions) {}

  get isActive(): boolean {
    return this.isStarted && !this.abort.signal.aborted;
  }

  refreshDue(): Promise<void> {
    return this.refreshDueWithin(0);
  }

  private refreshDueWithin(horizonMs: number): Promise<void> {
    if (this.cycle) return this.cycle;
    if (this.abort.signal.aborted) return Promise.resolve();
    this.cycle = this.runDue(horizonMs).finally(() => {
      this.cycle = undefined;
    });
    return this.cycle;
  }

  private async runDue(horizonMs: number): Promise<void> {
    const deadline = Date.now() + horizonMs;
    const current = await this.options.checks();
    this.abort.signal.throwIfAborted();
    const due =
      current?.checks.filter((check) => check.dueAt <= deadline) ?? [];
    if (current && due.length)
      await this.options.refresh({
        accountId: current.accountId,
        checks: due,
        signal: this.abort.signal,
      });
  }

  start(): void {
    if (this.isStarted || this.abort.signal.aborted) return;
    this.isStarted = true;
    this.wake = this.tick(LOCAL_SOURCE_POLL_MS);
  }

  private async tick(horizonMs = 0): Promise<void> {
    try {
      await this.refreshDueWithin(horizonMs);
    } catch {
      if (!this.abort.signal.aborted)
        log.warn('Background source sync could not refresh due sources');
    }
    if (this.abort.signal.aborted) return;
    const current = await this.options.checks().catch(() => null);
    if (this.abort.signal.aborted) return;
    const now = Date.now();
    const next = Math.min(
      now + LOCAL_SOURCE_POLL_MS,
      ...(current?.checks.map((check) => check.dueAt) ?? []),
    );
    this.timer = setTimeout(
      () => {
        this.wake = this.tick();
      },
      Math.min(MAX_TIMER_MS, Math.max(MIN_WAKE_MS, next - now)),
    );
    this.timer.unref();
  }

  async close(): Promise<void> {
    if (this.timer) clearTimeout(this.timer);
    this.abort.abort();
    await this.cycle?.catch(() => undefined);
    await this.wake;
  }
}
